"""Plates for The Cloud on the Ground's part decide1 (sprint 059): zoning and the Digital Gateway.
See plates_for.py."""
import math
from plates import D, hatch, clip


def _arrow(d, p, q, size=5):
    """An arrowhead at q, pointing from p."""
    a = math.atan2(q[1] - p[1], q[0] - p[0])
    l = (q[0] - size * math.cos(a - 0.45), q[1] - size * math.sin(a - 0.45))
    r = (q[0] - size * math.cos(a + 0.45), q[1] - size * math.sin(a + 0.45))
    d.line(l, q, r)


def _box(d, x, y, w, h):
    d.line((x, y), (x + w, y), (x + w, y + h), (x, y + h), closed=True)


def _rect(x0, y0, x1, y1):
    return [(x0, y0), (x1, y0), (x1, y1), (x0, y1)]


def zoning():
    """A zoning map as geometry, labeled a schematic: residential, office, industrial and
    agricultural districts; an overlay over two of them; a data center in the industrial district
    with its setback from the residential line; and an agricultural parcel rezoned to industrial."""
    d = D()
    R = _rect(16, 34, 150, 196)
    O = _rect(150, 34, 384, 108)
    I = _rect(150, 108, 384, 196)
    A = _rect(16, 212, 384, 284)
    setback = 44                      # plate units from the residential line to the building
    bx0, by0, bx1, by1 = 150 + setback, 126, 330, 180
    parcel = _rect(232, 222, 368, 276)

    d.group('thin')
    # the road between the districts, and the lot grid of the residential district
    d.line((8, 200), (392, 200))
    d.line((8, 208), (392, 208))
    for x in range(40, 150, 24):
        d.line((x, 34), (x, 196))
    for y in range(64, 196, 30):
        d.line((16, y), (150, y))
    # field rows in the agricultural district, clipped round the rezoned parcel
    d.lines([[(20, y), (226, y)] for y in range(220, 284, 8)])

    d.group()
    # the districts
    for poly in (R, O, I, A):
        d.line(*poly, closed=True)
    # the data center in the industrial district, in modules
    _box(d, bx0, by0, bx1 - bx0, by1 - by0)
    for k in range(1, 4):
        x = bx0 + k * (bx1 - bx0) / 4
        d.line((x, by0), (x, by1))
    # houses on their lots
    for x in range(28, 140, 24):
        for y in range(44, 190, 30):
            _box(d, x, y, 10, 9)

    d.group('mid')
    # the industrial district hatched round the building, leaving the setback and a strip for its name
    for strip in (_rect(bx1, by0, 384, 196), _rect(bx0, by1, bx1, 196)):
        d.lines(hatch(strip, 8, 45))
    # the overlay district over office and industrial, dashed
    d.dashed((168, 42), (376, 42), (376, 190), (168, 190), (168, 42), dash=6, gap=4)
    # the setback, dimensioned from the residential line to the building
    yy = 156
    d.line((150, yy), (bx0, yy))
    _arrow(d, (160, yy), (150, yy), 4)
    _arrow(d, (bx0 - 10, yy), (bx0, yy), 4)
    # the rezoned parcel, dashed and hatched as industrial, and its arrow from the industrial district
    d.dashed(*parcel, parcel[0], dash=5, gap=3)
    d.lines(hatch(parcel, 8, 45))
    d.line((300, 186), (300, 218))
    _arrow(d, (300, 206), (300, 218), 5)

    d.group('labels')
    d.text(83, 30, 'RESIDENTIAL', size=7)
    d.text(267, 30, 'OFFICE', size=7)
    d.text(262, 156, 'DATA CENTER', size=7)
    d.text(bx0 + 4, 120, 'INDUSTRIAL', size=7, anchor='start')
    d.text(68, 232, 'AGRICULTURAL', size=7)
    d.text(bx0 - setback / 2, yy - 6, 'SETBACK', size=7)
    d.text(370, 54, 'OVERLAY', size=7, anchor='end')
    d.text(306, 216, 'REZONED', size=7, anchor='start')
    d.text(384, 296, 'SCHEMATIC', size=7, anchor='end')
    return d


