def digital_gateway():
    """The Digital Gateway in plan: the approximate limits of disturbance of its three rezonings
    (Compass in the middle, hatched one way; Digital Gateway North and South, QTS's, the other),
    their planned substations, Pageland Lane, US 29 and Route 234, the two 500-kilovolt lines
    across the corridor, and the boundary of Manassas National Battlefield Park. Geometry from
    Prince William County's Digital Gateway map service and its transmission-line layer, the
    National Park Service's boundary of the park and the Census Bureau's TIGER roads, projected
    equirectangular at 38.83 N (lon -77.607 to -77.525, lat 38.808 to 38.857), north up."""
    d = D()
    frame = _rect(0, 0, 400, 300)
    km = 51.33                    # plate units per kilometer at the projection's scale

    def cl(pts):
        return clip(list(pts), frame)

    d.group('thin')
    for p in LINES_500KV:
        d.lines(cl(p))
    for key in ('US29', 'VA234', 'VA234B'):
        for p in ROADS[key]:
            d.lines(cl(p))
    # scale bar of one kilometer, and a north arrow
    x0, y0 = 300, 288
    d.line((x0, y0), (x0 + km, y0))
    for x in (x0, x0 + km / 2, x0 + km):
        d.line((x, y0 - 3), (x, y0 + 3))
    d.line((384, 40), (384, 16))
    _arrow(d, (384, 26), (384, 16), 5)

    d.group()
    for ring in PARK:
        d.lines(cl(list(ring) + [ring[0]]))
    for key in ('compass', 'north', 'south'):
        for ring in GATEWAY[key]:
            d.line(*ring, closed=True)

    d.group('mid')
    for key, angle in (('compass', 45), ('north', -45), ('south', -45)):
        for ring in GATEWAY[key]:
            d.lines(hatch(list(ring), 4, angle))
    for (x, y) in SUBSTATIONS:
        _box(d, x - 2.5, y - 2.5, 5, 5)
    for p in ROADS['PAGELAND']:
        d.lines(cl(p))

    d.group('labels')
    d.text(318, 150, 'MANASSAS NATIONAL', size=7)
    d.text(318, 159, 'BATTLEFIELD PARK', size=7)
    d.text(x0 + km / 2, y0 - 6, '1 KM', size=7)
    d.text(384, 50, 'N', size=7)
    d.text(160, 292, 'PAGELAND LN', size=7, anchor='end')
    d.text(318, 264, 'US 29', size=7)
    d.text(332, 88, 'VA 234', size=7, anchor='start')
    d.text(216, 162, '500 KV', size=7, anchor='start')
    d.text(88, 150, 'COMPASS', size=7, anchor='end')
    d.text(250, 24, 'QTS', size=7, anchor='start')
    d.text(102, 246, 'QTS', size=7, anchor='end')
    return d


PLATES = {'zoning': zoning, 'digital-gateway': digital_gateway}
